import React from 'react';
import { Prediction } from '../types';
import { MODEL_CONFIG, CATEGORY_ICONS } from '../constants';
import { CheckCircle, XCircle, Clock, ChevronRight } from 'lucide-react';

interface PredictionCardProps {
  prediction: Prediction;
  onStatusChange: (id: string, status: Prediction['status']) => void;
}

export const PredictionCard: React.FC<PredictionCardProps> = ({ prediction, onStatusChange }) => {
  const model = MODEL_CONFIG[prediction.model];

  const statusIcon = {
    'Pending': <Clock className="w-4 h-4 text-slate-400" />,
    'Success': <CheckCircle className="w-4 h-4 text-emerald-400" />,
    'Failed': <XCircle className="w-4 h-4 text-rose-400" />,
    'Partial': <div className="w-4 h-4 rounded-full border-2 border-amber-400 border-t-transparent animate-spin" />
  };

  const statusColors = {
    'Pending': 'bg-slate-500/10 text-slate-400',
    'Success': 'bg-emerald-500/10 text-emerald-400',
    'Failed': 'bg-rose-500/10 text-rose-400',
    'Partial': 'bg-amber-500/10 text-amber-400'
  };

  return (
    <div className="glass rounded-2xl p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl hover:shadow-blue-500/5 group flex flex-col h-full">
      <div className="flex justify-between items-start mb-4">
        <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full ${model.bg}`}>
          <span className={model.color}>{model.icon}</span>
          <span className={`text-xs font-bold uppercase tracking-wider ${model.color}`}>{prediction.model}</span>
        </div>
        <div className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-tighter ${statusColors[prediction.status]}`}>
          {statusIcon[prediction.status]}
          {prediction.status}
        </div>
      </div>

      <div className="flex items-center gap-2 mb-3">
        <span className="p-1.5 rounded-lg bg-white/5 text-slate-300">
          {CATEGORY_ICONS[prediction.category]}
        </span>
        <span className="text-xs font-medium text-slate-400">{prediction.category}</span>
      </div>

      <p className="text-slate-100 text-lg leading-relaxed mb-6 font-medium flex-grow">
        "{prediction.content}"
      </p>

      <div className="space-y-4">
        <div className="w-full bg-white/5 h-1.5 rounded-full overflow-hidden">
          <div 
            className="h-full bg-gradient-to-r from-blue-500 to-cyan-400 rounded-full transition-all duration-1000"
            style={{ width: `${prediction.confidence}%` }}
          />
        </div>

        <div className="flex justify-between items-center text-xs">
          <span className="text-slate-500 font-medium tracking-tight uppercase">Confidence Level</span>
          <span className="text-cyan-400 font-bold">{prediction.confidence}%</span>
        </div>

        {/* Demo Controls: In a real app these would be admin-only */}
        <div className="pt-4 border-t border-white/5 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={() => onStatusChange(prediction.id, 'Success')}
            className="flex-1 py-1.5 rounded-md text-[10px] font-bold uppercase tracking-widest bg-emerald-500/20 text-emerald-400 hover:bg-emerald-500/40 transition-colors"
          >
            Mark Success
          </button>
          <button 
            onClick={() => onStatusChange(prediction.id, 'Failed')}
            className="flex-1 py-1.5 rounded-md text-[10px] font-bold uppercase tracking-widest bg-rose-500/20 text-rose-400 hover:bg-rose-500/40 transition-colors"
