import React from 'react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell,
  PieChart,
  Pie
} from 'recharts';
import { Prediction, LLM } from '../types';
import { MODEL_CONFIG } from '../constants';

interface StatsProps {
  predictions: Prediction[];
}

export const Stats: React.FC<StatsProps> = ({ predictions }) => {
  const modelStats = predictions.reduce((acc, curr) => {
    if (!acc[curr.model]) {
      acc[curr.model] = { name: curr.model, count: 0, confidence: 0 };
    }
    acc[curr.model].count += 1;
    acc[curr.model].confidence += curr.confidence;
    return acc;
  }, {} as Record<string, any>);

  const chartData = Object.values(modelStats).map(m => ({
    ...m,
    avgConfidence: Math.round(m.confidence / m.count)
  }));

  const categoryData = predictions.reduce((acc, curr) => {
    const existing = acc.find(a => a.name === curr.category);
    if (existing) {
      existing.value += 1;
    } else {
      acc.push({ name: curr.category, value: 1 });
    }
    return acc;
  }, [] as { name: string; value: number }[]);

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#64748b'];

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-12">
      <div className="glass rounded-3xl p-8">
        <h3 className="text-xl font-bold mb-6 text-slate-100 flex items-center gap-2">
          Model Confidence Distribution
          <span className="text-xs font-normal text-slate-500 bg-white/5 px-2 py-1 rounded">Avg. Score</span>
        </h3>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
              <XAxis dataKey="name" stroke="#64748b" fontSize={12} axisLine={false} tickLine={false} />
              <YAxis hide />
              <Tooltip 
                contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '12px' }}
                itemStyle={{ color: '#f8fafc' }}
              />
              <Bar dataKey="avgConfidence" radius={[8, 8, 0, 0]} barSize={40}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={MODEL_CONFIG[entry.name as LLM].color.replace('text-', '#').replace('-400', '') || '#3b82f6'} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="glass rounded-3xl p-8">
        <h3 className="text-xl font-bold mb-6 text-slate-100 flex items-center gap-2">
          Thematic Focus
          <span className="text-xs font-normal text-slate-500 bg-white/5 px-2 py-1 rounded">Prediction Count</span>
        </h3>
        <div className="h-64 w-full flex items-center justify-center">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={categoryData}
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
              >
                {categoryData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip 
                contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: '12px' }}
                itemStyle={{ color: '#f8fafc' }}
              />
            </PieChart>
          </ResponsiveContainer>
          <div className="flex flex-col gap-2 max-h-64 overflow-y-auto pl-4 custom-scrollbar">
            {categoryData.map((c, i) => (
              <div key={c.name} className="flex items-center gap-2 text-xs">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                <span className="text-slate-400">{c.name}:</span>
                <span className="text-slate-100 font-bold">{c.value}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Scope, Category, Prediction, LLM } from './types';
import { PREDICTIONS_DATA } from './data';
import { SCOPE_ICONS, CATEGORY_ICONS } from './constants';
import { PredictionCard } from './components/PredictionCard';
import { Stats } from './components/Stats';
import { LayoutGrid, BarChart3, Info, Github, Calendar, Filter } from 'lucide-react';

const App: React.FC = () => {
  const [activeScope, setActiveScope] = useState<Scope | 'All'>('All');
  const [activeCategory, setActiveCategory] = useState<Category | 'All'>('All');
  const [view, setView] = useState<'Grid' | 'Analytics'>('Grid');
  const [predictions, setPredictions] = useState<Prediction[]>(PREDICTIONS_DATA);

  const filteredPredictions = useMemo(() => {
    return predictions.filter(p => {
      const scopeMatch = activeScope === 'All' || p.scope === activeScope;
      const categoryMatch = activeCategory === 'All' || p.category === activeCategory;
      return scopeMatch && categoryMatch;
    });
  }, [activeScope, activeCategory, predictions]);

  const categories = Array.from(new Set(predictions.map(p => p.category))).sort();
  const scopes: Scope[] = ['Brazil', 'Global', 'Geopolitics'];

  const handleStatusChange = (id: string, status: Prediction['status']) => {
    setPredictions(prev => prev.map(p => p.id === id ? { ...p, status } : p));
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 pb-20 selection:bg-blue-500/30">
      {/* Header */}
      <header className="relative py-20 px-6 overflow-hidden">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-full max-w-4xl h-96 bg-blue-600/20 blur-[120px] rounded-full -z-10" />
        <div className="max-w-6xl mx-auto text-center">
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/5 border border-white/10 mb-8 backdrop-blur-sm">
            <Calendar className="w-4 h-4 text-blue-400" />
            <span className="text-xs font-bold uppercase tracking-widest text-slate-400">Projected for 2025</span>
          </div>
          <h1 className="text-5xl md:text-7xl font-black mb-6 tracking-tight bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400">
            LLM Oracle
          </h1>
          <p className="text-lg md:text-xl text-slate-400 max-w-2xl mx-auto leading-relaxed">
            Comparing the strategic foresight of 5 leading AI models. 36 predictions. 12 months. 1 definitive truth.
          </p>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6">
        {/* Navigation & Controls */}
        <div className="flex flex-col lg:flex-row gap-6 items-center justify-between mb-12 sticky top-6 z-40">
          <div className="glass p-1.5 rounded-2xl flex gap-1 w-full lg:w-auto shadow-2xl">
            <button 
              onClick={() => setActiveScope('All')}
              className={`flex-1 lg:flex-none px-6 py-2.5 rounded-xl text-sm font-bold transition-all duration-200 ${activeScope === 'All' ? 'bg-white/10 text-white shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}
            >
              All Scopes
            </button>
            {scopes.map(scope => (
              <button 
                key={scope}
                onClick={() => setActiveScope(scope)}
                className={`flex-1 lg:flex-none px-6 py-2.5 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all duration-200 ${activeScope === scope ? 'bg-white/10 text-white shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}
              >
                {SCOPE_ICONS[scope]}
                {scope}
              </button>
            ))}
          </div>

          <div className="glass p-1.5 rounded-2xl flex gap-1 w-full lg:w-auto shadow-2xl">
            <button 
              onClick={() => setView('Grid')}
              className={`flex-1 lg:flex-none px-4 py-2.5 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all duration-200 ${view === 'Grid' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <LayoutGrid className="w-4 h-4" />
              Predictions
            </button>
            <button 
              onClick={() => setView('Analytics')}
              className={`flex-1 lg:flex-none px-4 py-2.5 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition-all duration-200 ${view === 'Analytics' ? 'bg-blue-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <BarChart3 className="w-4 h-4" />
              Analytics
            </button>
          </div>
        </div>

        {/* Filters Bar */}
        <div className="flex items-center gap-4 mb-10 overflow-x-auto pb-4 no-scrollbar">
          <div className="flex items-center gap-2 text-slate-500 shrink-0">
            <Filter className="w-4 h-4" />
            <span className="text-xs font-bold uppercase tracking-wider">Themes:</span>
          </div>
          <button 
            onClick={() => setActiveCategory('All')}
            className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap transition-all border ${activeCategory === 'All' ? 'bg-white text-slate-950 border-white' : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/20'}`}
          >
            All Themes
          </button>
          {categories.map(cat => (
            <button 
              key={cat}
              onClick={() => setActiveCategory(cat as Category)}
              className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap flex items-center gap-2 transition-all border ${activeCategory === cat ? 'bg-white text-slate-950 border-white' : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/20'}`}
            >
              {CATEGORY_ICONS[cat as Category]}
              {cat}
            </button>
          ))}
        </div>

        {/* Content View */}
        {view === 'Grid' ? (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {filteredPredictions.map(p => (
                <PredictionCard 
                  key={p.id} 
                  prediction={p} 
                  onStatusChange={handleStatusChange} 
                />
              ))}
            </div>
            {filteredPredictions.length === 0 && (
              <div className="py-40 text-center">
                <Info className="w-12 h-12 text-slate-700 mx-auto mb-4" />
                <p className="text-slate-500 font-medium">No predictions match your selected filters.</p>
              </div>
            )}
          </>
        ) : (
          <Stats predictions={predictions} />
        )}
      </main>

      {/* Footer */}
      <footer className="mt-40 border-t border-white/5 py-12 px-6">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-8">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-blue-600 flex items-center justify-center font-black text-white italic">O</div>
            <span className="font-bold text-slate-200">LLM Oracle Project</span>
          </div>
          <p className="text-sm text-slate-500 text-center md:text-left">
            This is a benchmarking sandbox for large language models. Verification starts Dec 2025.
          </p>
          <div className="flex gap-6">
            <a href="#" className="text-slate-500 hover:text-white transition-colors"><Github className="w-5 h-5" /></a>
            <a href="#" className="text-slate-500 hover:text-white transition-colors uppercase text-xs font-bold tracking-widest">About</a>
            <a href="#" className="text-slate-500 hover:text-white transition-colors uppercase text-xs font-bold tracking-widest">Methodology</a>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

