            <button onClick={() => setView('Analytics')} className="text-left text-sm font-bold text-slate-500 hover:text-blue-400 transition-colors">Analytics</button>
            <button onClick={() => setView('Grid')} className="text-left text-sm font-bold text-slate-500 hover:text-blue-400 transition-colors">Predictions Grid</button>
