              <div className="flex-grow glass p-3 rounded-xl text-center text-[10px] font-black uppercase tracking-widest text-slate-500 border-white/5">
                v1.1.0-STABLE
              </div>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

