  category: Category;
  content: string;
  confidence: number; // 0 to 100
  status: Status;
  timestamp: string;
  reasoning?: string;
}

export interface Statistics {
  total: number;
  byModel: Record<LLM, { success: number; failed: number; pending: number }>;
}

