  | 'Tech' 
  | 'AI' 
  | 'Crypto' 
  | 'Finance & Economy' 
  | 'Sports';

export type Status = 'Pending' | 'Confirmed' | 'Debunked' | 'Ongoing';

export interface EvidenceSource {
  title: string;
  url: string;
  sourceName: string;
  date: string;
}

export interface Prediction {
  id: string;
