    const updated = predictions.map(p => {
      if (p.id === id) {
        return { ...p, status };
      }
      return p;
    });
    setPredictions(updated);
    if (selectedPrediction?.id === id) {
      setSelectedPrediction({ ...selectedPrediction, status });
    }
  };

  const handleAdminLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (adminPassword === 'oracle2026') {
