            </span>
          </div>
          <h1 
            className="text-6xl md:text-8xl font-black mb-6 tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-500 cursor-pointer select-none" 
            onClick={() => setView('Grid')}
