  | 'Tech' 
  | 'AI' 
  | 'Crypto' 
  | 'Finance & Economy' 
  | 'Sports';

export type Status = 'Pending' | 'Confirmed' | 'Debunked' | 'Ongoing';

export interface Prediction {
  id: string;
  code: string; 
  model: LLM;
  scope: Scope;
  category: Category;
  title: string;      // From "Title" in PDF
